function ux_measure($scenario,$rep,$fn,$notes=''){
 global $wpdb,$records,$queriesOut;$start=count($wpdb->queries);$before=ux_f0_db_snapshot();$numBefore=$wpdb->num_queries;$t=hrtime(true);$out=$fn();$ms=(hrtime(true)-$t)/1e6;$after=ux_f0_db_snapshot();$pfsMs=$after['ms']-$before['ms'];$pfsCount=$after['count']-$before['count'];$qs=array_slice($wpdb->queries,$start);$db=0;$unique=array();$types=array();foreach($qs as $q){$db+=$q[1]*1000;$h=hash('sha256',$q[0]);$unique[$h]=($unique[$h]??0)+1;$type=strtoupper(strtok(ltrim($q[0])," \n\r\t"));$types[$type]=($types[$type]??0)+1;}
 $records[]=array('scenario'=>$scenario,'environment'=>'local-wordpress-owner','repetition'=>$rep,'total_ms'=>$ms,'queue_ms'=>'NA','client_pre_ms'=>'NA','network_server_ms'=>'NA','php_ms'=>$ms,'db_ms'=>$pfsMs,'parse_restore_ms'=>'NA','render_ms'=>'NA','stable_ms'=>'NA','notes'=>$notes.'; same CLI WP process, setup excluded; inclusive owner duration');$queriesOut[]=array('scenario'=>$scenario,'repetition'=>$rep,'environment'=>'local-wordpress-owner','query_count'=>$pfsCount,'wpdb_num_queries'=>$wpdb->num_queries-$numBefore,'wpdb_logged_queries'=>count($qs),'db_ms'=>$pfsMs,'wpdb_db_ms'=>$db,'duplicate_exact_queries'=>array_sum(array_map(static function($n){return max(0,$n-1);},$unique)),'query_classes'=>$types);return $out;
}
