 $ch=curl_init('http://127.0.0.1'.$path);$set=array();curl_setopt_array($ch,array(CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>$headers,CURLOPT_TIMEOUT=>25,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_HEADERFUNCTION=>static function($c,$line)use(&$set){if(stripos($line,'Set-Cookie:')===0){$cookie=explode(';',trim(substr($line,11)))[0];list($n,$v)=explode('=',$cookie,2);$set[]=new WP_Http_Cookie(array('name'=>$n,'value'=>urldecode($v)));}return strlen($line);}));if($body!==null){curl_setopt($ch,CURLOPT_POST,true);curl_setopt($ch,CURLOPT_POSTFIELDS,http_build_query($body));}
