 $requestComponents=isset($body['payload'])?json_decode($body['payload'],true):array();$responseFrame=$data['data']??array();if(!is_array($responseFrame))$responseFrame=array();if(!$json&&preg_match('/window\.eipsiNativeParticipant=(.*?);<\/script>/s',$raw,$m))$responseFrame=json_decode($m[1],true)['frame']??array();$componentBytes=static function($value){return $value===null?0:strlen(json_encode($value));};
 $records[]=array('scenario'=>$scenario,'environment'=>'local-wordpress-http','repetition'=>$rep,'total_ms'=>$ms,'queue_ms'=>'NA','client_pre_ms'=>'NA','network_server_ms'=>$ms,'php_ms'=>'NA','db_ms'=>'NA','parse_restore_ms'=>$parse,'render_ms'=>'NA','stable_ms'=>'NA','notes'=>'Internal HTTP; curl TTFB '.round($info['starttransfer_time']*1000,3).' ms; connect '.round($info['connect_time']*1000,3).' ms; HTTP '.$info['http_code']);$payloadsOut[]=array('scenario'=>$scenario,'repetition'=>$rep,'request_body_bytes'=>$body===null?0:strlen(http_build_query($body)),'response_body_bytes'=>strlen($raw),'response_gzip_estimate_bytes'=>strlen(gzencode($raw)),'request_answers_json_bytes'=>$componentBytes($requestComponents['answers']??null),'request_metadata_json_bytes'=>$componentBytes($requestComponents['metadata']??null),'response_definition_json_bytes'=>$componentBytes($responseFrame['definition']??null),'response_metadata_json_bytes'=>$componentBytes($responseFrame['metadata']??null),'response_session_json_bytes'=>$componentBytes($responseFrame['session']??null),'connect_ms'=>$info['connect_time']*1000,'ttfb_ms'=>$info['starttransfer_time']*1000,'after_ttfb_ms'=>($info['total_time']-$info['starttransfer_time'])*1000,'compression'=>'estimate only; internal HTTP uncompressed');
 if(!$json){preg_match_all('/<(?:script|link|img)\b[^>]*(?:src|href)=["\x27]([^"\x27]+)["\x27][^>]*>/i',$raw,$matches);foreach($matches[1] as $url){$p=parse_url(html_entity_decode($url),PHP_URL_PATH);if(strpos($p,'/wp-content/plugins/EIPSI-Forms-Plugin/')===0)$assetsOut[]=array('scenario'=>$scenario,'path'=>substr($p,strlen('/wp-content/plugins/EIPSI-Forms-Plugin/')));elseif(strpos($p,'/wp-')===0)$assetsOut[]=array('scenario'=>$scenario,'path'=>$p);}}
 return array('status'=>$info['http_code'],'body'=>$raw,'data'=>$data,'cookies'=>$set?:$cookies);
